import { describe, it, expect } from 'vitest';
import fs from 'fs';
import path from 'path';
import { assignModesQuantile } from '../src/schema/usirForge.js';

// Fixture generated by python/tests/test_phase26_forge_modes.py (usir_forge.assign_modes_quantile).
describe('Phase 26.1 quantile mode assignment: Python parity', () => {
  const fx = JSON.parse(
    fs.readFileSync(path.resolve(__dirname, 'fixtures', 'quantile_modes_parity.json'), 'utf-8'),
  ) as { cases: { Z: number[][]; dialogue: number[]; modes: number[] }[] };

  it('matches the Python assignment on all fixture cases', () => {
    for (const c of fx.cases) {
      expect(assignModesQuantile(c.Z, c.dialogue)).toEqual(c.modes);
    }
  });

  it('falls back (null) below 20 windows', () => {
    const Z = Array.from({ length: 19 }, () => new Array<number>(24).fill(0.5));
    expect(assignModesQuantile(Z, new Array<number>(19).fill(0))).toBeNull();
  });
});
